        static void Combo(ComboBox control,string name,int width){control.Name=name;control.DropDownStyle=ComboBoxStyle.DropDownList;control.Width=width;control.ForeColor=SystemColors.WindowText;control.BackColor=SystemColors.Window;}
        static Button Button(string name,string text){return new Button{Name=name,Text=text,AutoSize=true,MinimumSize=new Size(78,32),ForeColor=SystemColors.ControlText,BackColor=SystemColors.Control,UseVisualStyleBackColor=true};}
        void Prepare(){if(IsDisposed||Disposing)return;appliedConfigured=(int)configured.Value;appliedCurrent=(int)current.Value;appliedMode=modes[mode.SelectedIndex];appliedPattern=pattern.SelectedIndex==0?(byte)0x6d:(byte)0xa7;applied=PracticeParticipantCompletion.CreateInspectionFixture(appliedCurrent,appliedPattern);StateSnapshot=null;Sync();}
        void Complete(bool again){if(IsDisposed||Disposing)return;var result=StateSnapshot;byte[] input=again&&result!=null?result.CopyRecords():applied;int count=again&&result!=null?result.FinalCount:appliedCurrent;StateSnapshot=PracticeParticipantCompletion.Complete(input,appliedConfigured,count,appliedMode);Sync();}
        void Pending(){if(applied==null||IsDisposed||Disposing)return;bool same=appliedConfigured==(int)configured.Value&&appliedCurrent==(int)current.Value&&appliedMode==modes[mode.SelectedIndex]&&appliedPattern==(pattern.SelectedIndex==0?0x6d:0xa7);pending.Text=same?"Controls match the applied copy.":"Selection pending. Prepare applies controls; Reset retains the applied copy.";}
