        {
            if(applied==null||IsDisposed||Disposing)return;var result=StateSnapshot;byte[] shown=result==null?applied:result.CopyRecords();int final=result==null?appliedCurrent:result.FinalCount;
            summary.Text="Applied configured total: "+appliedConfigured+" · fixture current records: "+appliedCurrent+" · mode: "+appliedMode+"\r\n"+(result==null?"Prepared copy; source completion has not run.":"Latest call: current "+result.InitialCount+" -> "+result.FinalCount+" · name requests "+result.NameRequests.Count+" · formation requests "+result.FormationRequests.Count)+"\r\n"+(final>appliedConfigured?"Oversubscribed count is retained; it cannot be used as a complete reinforcement setup.":"Use counts changes the parent selection only; Load in that study applies the pending counts.");
            records.Rows.Clear();for(int slot=0;slot<4;slot++){int at=slot*44,kind=BitConverter.ToInt32(shown,at),changed=0;for(int n=0;n<44;n++)if(shown[at+n]!=applied[at+n])changed++;string kindText=kind==0?"0 · unused":kind==1?"1 · existing":kind==2?"2 · appended":"opaque 0x"+unchecked((uint)kind).ToString("X8");string name=slot>=final?"(opaque bytes)":result==null?Display(shown,at+24):result.DisplayNameAt(slot);records.Rows.Add(slot,kindText,slot>=final?"retained":BitConverter.ToInt16(shown,at+4).ToString(),name,changed,slot<appliedCurrent?"Existing record":slot<final?"New type-2 record":"Outside current count");}
