        internal bool StudyKey(Keys key,bool down){if(key!=Keys.Enter&&key!=Keys.Escape)return false;if(!down){held.Remove(key);return true;}if(!held.Add(key))return true;if(key==Keys.Escape)Close();else Prepare();return true;}
        protected override bool ProcessCmdKey(ref Message message,Keys keyData){if(StudyKey(keyData&Keys.KeyCode,true))return true;return base.ProcessCmdKey(ref message,keyData);}
        protected override void OnKeyUp(KeyEventArgs e){if(StudyKey(e.KeyCode,false))e.Handled=true;base.OnKeyUp(e);}
        protected override void OnActivated(EventArgs e){base.OnActivated(e);foreach(Keys key in new[]{Keys.Enter,Keys.Escape})if((GetAsyncKeyState((int)key)&0x8000)!=0)held.Add(key);}
